func TestRecentWindowsRollupsFromKernelVersion(t *testing.T) {
	for _, tc := range []struct {
		release, build, firstKB, lastKB string
	}{
		{"Windows 10 Version 22H2 for x64-based Systems", "19045", "5032189", "5039211"},
		{"Windows 11 Version 22H2 for x64-based Systems", "22621", "5032190", "5039212"},
		{"Windows 11 Version 23H2 for x64-based Systems", "22631", "5032190", "5039212"},
		{"Windows Server 2022", "20348", "5032198", "5039227"},
	} {
		low, err := DetectKBsFromKernelVersion(tc.release, "10.0."+tc.build+".1")
		if err != nil {
			t.Fatal(err)
		}
		high, err := DetectKBsFromKernelVersion(tc.release, "10.0."+tc.build+".9999")
		if err != nil {
			t.Fatal(err)
		}
		for _, kb := range []string{tc.firstKB, tc.lastKB} {
			if !slices.Contains(low.Unapplied, kb) || !slices.Contains(high.Applied, kb) || slices.Contains(high.Unapplied, kb) {
				t.Errorf("%s: KB%s low=%+v high=%+v", tc.build, kb, low, high)
			}
		}
	}
}

